use vstd::prelude::*;

verus! {
    /// Function to calculate the monetary loss based on cost price and selling price.
    /// If cost_price > selling_price, loss = cost_price - selling_price.
    /// Otherwise, loss = 0.
    fn calculate_loss(cost_price: i32, selling_price: i32) -> (loss: i32)
        requires
            cost_price >= 0,
            selling_price >= 0,
        ensures
            loss == (if cost_price > selling_price { cost_price - selling_price } else { 0 }),
    {
        // Initialize loss to 0
        let mut loss: i32 = 0;

        // Check if cost price is greater than selling price
        if cost_price > selling_price {
            loss = cost_price - selling_price; // Calculate loss
        } else {
            loss = 0; // No loss
        }

        // Return the computed loss
        loss
    }
}

